function initial(){return {name:'New Tournament',game:'8-ball',race:3,entry:0,prize:false,format:'single',players:[],tables:[1,2,3,4].map(n=>({id:id(),name:`Table ${n}`,angles:[{id:'main',name:'Main view'}]})),rounds:[],scoring:'games',created:now(),demo:false}}
